css:
& { padding:0; gap:0; overflow:hidden; isolation:isolate; }
.st-photo { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; z-index:-3; }
.st-shade { position:absolute; inset:0; z-index:-2; background:linear-gradient(90deg,var(--bg),color-mix(in srgb,var(--bg) 90%,transparent) 28%,color-mix(in srgb,var(--bg) 20%,transparent) 74%),linear-gradient(0deg,color-mix(in srgb,var(--bg) 95%,transparent),transparent 70%); }
.st-head { position:absolute; left:100px; top:82px; width:1350px; }
.st-kicker { font:500 22px/1.3 var(--font-mono,var(--mono)); letter-spacing:.13em; text-transform:uppercase; color:var(--accent); }
.st-head h2 { font-family:var(--font-display,var(--font)); font-size:76px; line-height:1.06; max-width:27ch; margin:22px 0 0; text-wrap:balance; }
.st-head p:empty,.st-head h2:empty { display:none; }
.st-intro { font-size:28px; color:var(--muted); line-height:1.4; max-width:53ch; margin-top:24px!important; }
.st-items { list-style:none; padding:0; margin:0; }
.st-items li { opacity:1!important; transform:none!important; }
.st-items li b { display:block; font-weight:650; line-height:1.14; text-wrap:balance; overflow-wrap:anywhere; }
.st-items li span { display:block; line-height:1.4; overflow-wrap:anywhere; }
.st-endnote { position:absolute; left:100px; right:100px; bottom:95px; font-size:32px; line-height:1.3; color:var(--ink); opacity:0; transition:opacity .65s; max-width:58ch; }
&:has([data-template-end].in) .st-endnote,&:has([data-template-end]:not([data-step])) .st-endnote { opacity:1; }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&[data-body-motion="none"] * { transition:none!important; }
@media (prefers-reduced-motion:reduce) { & * { transition:none!important; animation:none!important; } }
.st-shade { background:linear-gradient(0deg,var(--bg),color-mix(in srgb,var(--bg) 15%,transparent) 75%),linear-gradient(90deg,color-mix(in srgb,var(--bg) 86%,transparent),color-mix(in srgb,var(--bg) 10%,transparent)); }
.at-orbit { position:absolute; left:1020px; top:395px; width:600px; height:450px; border:1px solid color-mix(in srgb,var(--accent) 35%,transparent); border-radius:50%; opacity:.35; transition:opacity .8s,border-color .8s; }
.at-orbit i { position:absolute; left:50%; top:50%; width:18px; height:18px; margin:-9px; background:var(--accent); border-radius:50%; box-shadow:0 0 60px var(--accent); }
.at-items { position:absolute; left:100px; top:420px; width:1640px; display:grid; grid-template-columns:1fr 1fr; column-gap:360px; row-gap:75px; counter-reset:insight; }
.at-items li { position:relative; padding-left:46px; counter-increment:insight; min-height:145px; opacity:.15!important; transition:opacity .7s; }
.at-items li::before { content:counter(insight,decimal-leading-zero); position:absolute; left:0; top:5px; font:21px/1.3 var(--font-mono,var(--mono)); color:var(--accent); }
.at-items li b { font-size:40px; }.at-items li span { font-size:28px; margin-top:18px; color:var(--muted); max-width:29ch; }
.at-items li.in { opacity:.62!important; }.at-items li.step-current { opacity:1!important; }.at-items li.step-current b { color:var(--accent); }
.at-items li:nth-child(2n) { padding:20px 30px 24px 65px; margin-top:-20px; background:color-mix(in srgb,var(--bg) 86%,transparent); border-radius:var(--radius,18px); }.at-items li:nth-child(2n)::before { left:20px; top:25px; }
&:has(.at-items li.step-current) .at-orbit { opacity:1; border-color:var(--accent); }
&:has([data-template-end].in), &:has([data-template-end]:not([data-step])) { .at-items li { opacity:1!important; }.at-items li b { color:var(--ink); }.at-orbit { opacity:1; border-color:var(--accent); }.st-endnote { color:var(--accent); font-size:38px; } }
